def data(self, *keys):
    """
    Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    data = {}
    for key in keys:
        if isinstance(key, int):
            if key < 0 or key >= len(self.items):
                raise IndexError("Index out of bounds")
            data[self.items[key].name] = self.items[key].value
        else:
            if key not in self.items:
                data[key] = None
            else:
                data[key] = self.items[key].value
    return data

def pop_u16(self):
    """ Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer.
    """
    return self.unpack('>H', 2)

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    class Point(Point):
        def __init__(self, x, y, srid=None):
            self.x = x
            self.y = y
            self.srid = srid

        def __repr__(self):
            return f"Point({self.x}, {self.y}, srid={self.srid})"

        def __eq__(self, other):
            return self.x == other.x and self.y == other.y and self.srid == other.srid

        def __hash__(self):
            return hash((self.x, self.y, self.srid))

        def __getstate__(self):
            return (self.x, self.y, self.srid)

        def __setstate__(self, state):
            self.x, self.y, self.srid = state

        def __reduce__(self):
            return (point_type, (self.x, self.y, self.srid))

    return Point

