                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, func)
    return decorator

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    def decorator(func):
        if not inspect.isfunction(func):
            raise ValueError('The @mru_cache decorator must be applied innermost of all decorators.')

        cache = collections.OrderedDict()

        @functools.wraps(func)
        def memoized(*args, **kwargs):
            key = (args, frozenset(kwargs.items())) if typed else args
            if key in cache:
                cache.move_to_end(key)
                return cache[key]
            result = func(*args, **kwargs)
            cache[key] = result
            if len(cache) > maxsize:
                cache.popitem(last=False)
            return result

        @contextmanager
        def put(*args, **kwargs):
            key = (args, frozenset(kwargs.items())) if typed else args
            yield functools.partial(cache.__setitem__, key)
        memoized.put = put

        def forget(*args, **kwargs):
            key = (args, frozenset(kwargs.items())) if typed else args
            if key in cache:
                del cache[key]
        memoized.forget = forget

        def clear():
            cache.clear()
        memoized.clear = clear

        return memoized
    return decorator

