def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes:
        return []
    bases = []
    for cls in classes:
        if cls not in bases:
            bases.append(cls)
            for base in cls.__bases__:
                if base not in bases:
                    bases.append(base)
    return bases

def namesAndDescriptions(self, all=False):
    """Return attribute names and descriptions defined by interface."""

    names = []
    descriptions = []

    for name, description in self.interface.items():
        if all or not name.startswith("_"):
            names.append(name)
            descriptions.append(description)

    return names, descriptions

def names(self, all=False):
    """Return the attribute names defined by the interface."""

    if all:
        return [attr for attr in dir(self) if not attr.startswith("_")]
    else:
        return [attr for attr in dir(self) if not attr.startswith("_") and not callable(getattr(self, attr))]

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    if Broken in getattr(sequence, '__bases__', ()):
        return [sequence]

    cls = sequence.__class__
    if InterfaceClass in cls.__mro__ or zope.interface.declarations.Implements in cls.__mro__:
        output.append(sequence)
    else:
        for v in sequence:
            _normalizeargs(v, output)

    return output

