def difference(d1, d2, level=-1):
    if level == 0:
        return d1
    result = {}
    for key in d1:
        if key not in d2:
            result[key] = d1[key]
        elif level == -1:
            result[key] = d1[key]
        elif isinstance(d1[key], dict):
            result[key] = difference(d1[key], d2[key], level - 1)
    return result

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not isinstance(coord, tuple) or len(coord) != 2:
        raise ValueError("coord must be a tuple of length 2")
    if not isinstance(weight, (int, float)):
        raise ValueError("weight must be a number")

    x, y = coord
    if not (self.xmin <= x <= self.xmax) or not (self.ymin <= y <= self.ymax):
        return

    x_index = int((x - self.xmin) / self.dx)
    y_index = int((y - self.ymin) / self.dy)
    self.data[y_index][x_index] += weight

    if self.auto_normalize:
        self.normalize()

