def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    if self.status == HouseStatus.RENTED:
        return prefix + "rented"
    elif self.status == HouseStatus.AUCTIONED:
        if self.highest_bid is not None:
            return prefix + "auctioned with highest bid of %d" % self.highest_bid
        else:
