def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Check if the inventory is a dictionary
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary")

    # Check if the inventory has the required fields
    required_fields = ["type", "version", "items"]
    for field in required_fields:
        if field not in inventory:
            raise ValueError(f"Inventory is missing required field: {field}")

    # Check if the type value is valid
    if extract_spec_version:
        type_value = inventory["type"]
        if not isinstance(type_value, str):
            raise ValueError("Type value must be a string")
        if type_value not in self.spec_versions:
            raise ValueError(f"Invalid type value: {type_value}")
        spec_version = type_value
    else:
        spec_version = self.spec_version

    # Check if the version value is valid
    version_value = inventory["version"]
    if not isinstance(version_value, str):
        raise ValueError("Version value must be a string")
    if version_value not in self.spec_versions[spec_version]:
        raise ValueError(f"Invalid version value: {version_value}")

    # Check if the items value is valid
    items_value = inventory["items"]
    if not isinstance(items_value, list):
        raise ValueError("Items value must be a list")
    for item in items_value:
        if not isinstance(item, dict):
            raise ValueError("Items value must be a list of dictionaries")
        for field in item:
            if field not in self.spec_versions[spec_version]["items"]:
                raise ValueError(f"Invalid field in item: {field}")

    # If all checks pass, return the inventory
    return inventory

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    for manifest_file in manifest_files:
        with open(manifest_file, "r") as f:
            manifest = json.load(f)
        for digest in manifest["digests"]:
            if digest not in digests_used:
                raise ValueError(f"Digest {digest} is not used in any APK")
    for digest in digests_used:
        if digest not in manifest["digests"]:
            raise ValueError(f"Digest {digest} is not present in any manifest")
    return True

def validate_as_prior_version(self, prior):
        """Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        if not isinstance(prior, InventoryValidator):
            raise ValueError("prior must be an InventoryValidator object")

        if self.inventory.size != prior.inventory.size:
            raise ValueError("Inventories must have the same size")

        for i in range(self.inventory.size):
            if self.inventory[i] != prior.inventory[i]:
                raise ValueError("Inventories must be identical")

        if self.constraints != prior.constraints:
            raise ValueError("Constraints must be identical")

        if self.parameters != prior.parameters:
            raise ValueError("Parameters must be identical")

        if self.priors != prior.priors:
            raise ValueError("Priors must be identical")

        if self.propensities != prior.propensities:
            raise ValueError("Propensities must be identical")

        if self.stoichiometry_matrix != prior.stoichiometry_matrix:
            raise ValueError("Stoichiometry matrix must be identical")

        if self.species != prior.species:
            raise ValueError("Species must be identical")

        if self.use_context != prior.use_context:
            raise ValueError("use_context must be identical")

        if self.validators != prior.validators:
            raise ValueError("Validators must be identical")

        return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """

    logical_path_map = {}

    for content_file in inventory.get_content_files(version):
        logical_path = content_file.get_logical_path()
        if logical_path not in logical_path_map:
            logical_path_map[logical_path] = set()
        logical_path_map[logical_path].add(content_file)

    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity must be a dictionary")

    if not isinstance(manifest_files, list):
        raise ValueError("Manifest files must be a list")

    for file in manifest_files:
        if file not in fixity:
            raise ValueError("File {} is not referenced in fixity".format(file))

    for file, checksum in fixity.items():
        if not isinstance(checksum, str):
            raise ValueError("Checksum for file {} must be a string".format(file))

        if not re.match(r"^[a-f0-9]{64}$", checksum):
            raise ValueError("Checksum for file {} is not a valid SHA-256 hash".format(file))

    return True

