def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for arg in args:
        if isinstance(arg, And):
            if arg.left == arg.right:
                new_args.append(arg.left)
            elif arg.left == Not(arg.right):
                new_args.append(arg.left)
            else:
                new_args.append(arg)
        elif isinstance(arg, Or):
            if arg.left == arg.right:
                new_args.append(arg.left)
            elif arg.left == Not(arg.right):
                new_args.append(arg.left)
            else:
                new_args.append(arg)
        else:
            new_args.append(arg)
    return new_args

def _fromutc(self, dt):
    """
    Given a timezone-aware datetime in a given timezone, calculates a
    timezone-aware datetime in a new timezone.

    Since this is the one time that we *know* we have an unambiguous
    datetime object, we take this opportunity to determine whether the
    datetime is ambiguous and in a "fold" state (e.g. if it's the first
    occurrence, chronologically, of the ambiguous datetime).

    :param dt:
        A timezone-aware :class:`datetime.datetime` object.
    """
    if not isinstance(dt, datetime):
        raise TypeError("dt must be a datetime object")
    if not dt.tzinfo:
        raise ValueError("dt must be a timezone-aware datetime object")

    # Determine whether the datetime is ambiguous and in a "fold" state
    if dt.tzinfo.fold:
        # If the datetime is ambiguous and in a "fold" state, we need to
        # determine which occurrence of the ambiguous datetime it is.
        # We do this by checking the previous and next occurrences of the
        # ambiguous datetime and comparing them to the given datetime.
        prev_occurrence = dt.tzinfo.fromutc(dt.replace(tzinfo=None) - timedelta(seconds=1))
        next_occurrence = dt.tzinfo.fromutc(dt.replace(tzinfo=None) + timedelta(seconds=1))
        if prev_occurrence.dst() != next_occurrence.dst():
            # The datetime is ambiguous and in a "fold" state, so we need to
            # determine which occurrence it is.
            if dt.dst() == prev_occurrence.dst():
                # The datetime is the first occurrence, chronologically, of the
                # ambiguous datetime.
                return dt.replace(tzinfo=self.tzinfo)
            else:
                # The datetime is the second occurrence, chronologically, of the
                # ambiguous datetime.
                return dt.replace(tzinfo=self.tzinfo) + timedelta(seconds=1)
        else:
            # The datetime is not ambiguous, so we can simply return it.
            return dt.replace(tzinfo=self.tzinfo)
    else:
        # The datetime is not ambiguous, so we can simply return it.
        return dt.replace(tzinfo=self.tzinfo)

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def inner_func(*args, **kwargs):
        if PY3:
            return namefunc(*args, **kwargs)
        else:
            return namefunc(*args, **kwargs).encode()
    return inner_func

