def render(pieces, style):
    """Render the given version pieces into the requested style."""

    if not pieces or not style:
        raise ValueError("Invalid input: pieces and style are required")

    if style not in ["major", "minor", "patch"]:
        raise ValueError("Invalid style: must be one of 'major', 'minor', or 'patch'")

    if len(pieces) != 3:
        raise ValueError("Invalid input: pieces must be a list of three elements")

    if not all(isinstance(x, int) for x in pieces):
        raise ValueError("Invalid input: pieces must be a list of integers")

    if any(x < 0 for x in pieces):
        raise ValueError("Invalid input: pieces must be non-negative integers")

    if style == "major":
        return "%d.0.0" % pieces[0]
    elif style == "minor":
        return "%d.%d.0" % (pieces[0], pieces[1])
    else:
        return "%d.%d.%d" % (pieces[0], pieces[1], pieces[2])

