def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    seen = set()
    queue = set([cls])

    while queue:
        c = queue.pop()
        seen.add(c)

        sc = c.__subclasses__()
        for c in sc:
            if c not in seen:
                queue.add(c)

    seen.remove(cls)
    return seen

def unquote(name):
    """Remove quote from the given name."""
    if len(name) > 1:
        if name.startswith('"') and name.endswith('"'):
            return name[1:-1].replace('\\\\', '\\').replace('\\"', '"')
        if name.startswith('<') and name.endswith('>'):
            return name[1:-1]
    return name

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        if sys.platform == 'win32':
            platform = 0
        else:
            platform = 1

    if platform == 0:
        # Windows/CMD
        pattern = r'((?:"[^"]*")|(?:\'[^\']*\')|(?:[^\s\'"]+))+'
    elif platform == 1:
        # POSIX
        pattern = r'((?:"[^"]*")|(?:\'[^\']*\')|(?:[^\s\'"]+))+'
    else:
        raise ValueError(f'Invalid platform value: {platform}')

    return re.findall(pattern, s)

def prepare_repository_from_archive(archive_path, filename=None, tmp_path="/tmp"):
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    if not os.path.exists(archive_path):
        raise ValueError("Archive path does not exist")

    if not os.path.isfile(archive_path):
        raise ValueError("Archive path is not a file")

    if not os.access(archive_path, os.R_OK):
        raise ValueError("Archive path is not readable")

    if not os.path.exists(tmp_path):
        raise ValueError("Temporary path does not exist")

    if not os.path.isdir(tmp_path):
        raise ValueError("Temporary path is not a directory")

    if not os.access(tmp_path, os.W_OK):
        raise ValueError("Temporary path is not writable")

    if filename is not None and not isinstance(filename, str):
        raise ValueError("Filename must be a string")

    if filename is not None and not os.path.isabs(filename):
        raise ValueError("Filename must be an absolute path")

    if filename is not None and not os.path.exists(filename):
        raise ValueError("Filename does not exist")

    if filename is not None and not os.path.isfile(filename):
        raise ValueError("Filename is not a file")

    if filename is not None and not os.access(filename, os.R_OK):
        raise ValueError("Filename is not readable")

    # Uncompress the archive
    subprocess.run(["tar", "-xzf", archive_path, "-C", tmp_path])

    # Get the file repo url
    repo_url = os.path.join(tmp_path, "repo")

    # Return the file repo url
    return repo_url

