def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not isinstance(commands, list):
        commands = [commands]
    if not isinstance(args, list):
        args = [args]
    for command in commands:
        if not isinstance(command, str):
            raise ValueError("command must be a string")
    for arg in args:
        if not isinstance(arg, str):
            raise ValueError("arg must be a string")
    if cwd is not None and not isinstance(cwd, str):
        raise ValueError("cwd must be a string")
    if env is not None and not isinstance(env, dict):
        raise ValueError("env must be a dict")
    if verbose and hide_stderr:
        raise ValueError("verbose and hide_stderr cannot both be True")
    if not commands:
        raise ValueError("commands must not be empty")
    if not args:
        raise ValueError("args must not be empty")
    if cwd is not None and not os.path.isdir(cwd):
        raise ValueError("cwd must be a valid directory")
    if env is not None and not all(isinstance(k, str) and isinstance(v, str) for k, v in env.items()):
        raise ValueError("env must be a dict of strings")
    if verbose:
        print("Running command:", " ".join(commands + args))
    if hide_stderr:
        stderr = subprocess.DEVNULL
    else:
        stderr = None
    try:
        subprocess.run(commands + args, cwd=cwd, env=env, stderr=stderr, check=True)
    except subprocess.CalledProcessError as e:
        raise RuntimeError("command failed with exit code {}".format(e.returncode))

