def hist_to_graph(hist, make_value=None, get_coordinate="left", field_names=("x", "y"), scale=None):
    if make_value is None:
        make_value = lambda bin_: bin_.content
    if get_coordinate == "left":
        get_coordinate = lambda bin_: bin_.left
    elif get_coordinate == "right":
        get_coordinate = lambda bin_: bin_.right
    elif get_coordinate == "middle":
        get_coordinate = lambda bin_: (bin_.left + bin_.right) / 2
    else:
        raise ValueError("Invalid get_coordinate argument")
    if scale is None:
        scale = hist.scale
    elif scale is True:
        scale = hist.scale
    else:
        raise ValueError("Invalid scale argument")
    graph = Graph(scale=scale, field_names=field_names)
    for bin_ in hist.bins:
        value = make_value(bin_)
        coordinate = get_coordinate(bin_)
        graph.add_point(coordinate, value)
    return graph

